//! The application icon: what ships inside the binary, and what each platform does with it.
//!
//! One 256² transparent PNG (`assets/app-icon/zenman.png`, generated by
//! `scripts/make-app-icon.py` from the prototype artwork) is the runtime icon on all three
//! desktops, and it is the whole runtime story on two of them:
//!
//! | desktop | who draws it | where the bytes come from |
//! |---|---|---|
//! | Windows | eframe → `WM_SETICON` for the window, taskbar and alt-tab; winit → `_NET_WM_ICON` equivalent | [`window_icon`] |
//! | macOS | eframe → `setApplicationIconImage`, i.e. the Dock tile and the app menu, on macOS 11+ | [`window_icon`] |
//! | Linux/X11 | winit → `_NET_WM_ICON`, which is what a taskbar or a dock reads for an untracked window | [`window_icon`] |
//!
//! Two things the runtime bytes cannot do, and their two owners:
//!
//! * **Windows Explorer, the desktop shortcut and `zenman.exe` itself** read the icon out of the
//!   executable's resource table, not out of memory. That is `build.rs`, which compiles
//!   `assets/app-icon/zenman.ico` into the binary as `RT_GROUP_ICON` (`winresource`, MIT).
//! * **Wayland compositors** (GNOME Shell, KWin) have no window-icon request to answer: they resolve
//!   an icon by matching the window's `app_id` against a `.desktop` file in an icon theme. Nothing a
//!   process can do at runtime changes that, so [`crate::desktop_entry`] writes both halves of the
//!   pairing into `$XDG_DATA_HOME` on request (`--install-desktop-entry`), user-scoped, no root.
//!
//! On X11 the icon therefore works with no desktop file at all, which is the point: `cargo run`,
//! a raw tarball binary and a `.desktop`-less system all get the right picture in the title bar, the
//! taskbar and the alt-tab switcher.

use std::sync::OnceLock;

/// The runtime icon: 256² RGBA, the field matted out of the artwork.
///
/// 256 is the largest side any of the three shells asks a *window* icon for (Windows' alt-tab at
/// 200 % scaling, a maximised macOS Dock tile, a HiDPI panel), and it costs ~64 KiB in the binary.
const ICON_PNG: &[u8] = include_bytes!("../../../assets/app-icon/zenman.png");

/// Linux only: the hicolor-icon-theme ladder, installed beside the `.desktop` file by
/// [`crate::desktop_entry`]. The side is the pixel width, and the theme spec names these exact
/// directories, so a DE that wants 22 px takes the 24 and scales it — shipping more sizes buys nothing.
#[cfg(target_os = "linux")]
pub const HICOLOR: [(u32, &[u8]); 5] = [
    (
        16,
        include_bytes!("../../../assets/app-icon/linux/16x16.png"),
    ),
    (
        32,
        include_bytes!("../../../assets/app-icon/linux/32x32.png"),
    ),
    (
        48,
        include_bytes!("../../../assets/app-icon/linux/48x48.png"),
    ),
    (
        128,
        include_bytes!("../../../assets/app-icon/linux/128x128.png"),
    ),
    (
        256,
        include_bytes!("../../../assets/app-icon/linux/256x256.png"),
    ),
];

/// The file name the icon theme knows this icon by, and the value of the desktop entry's `Icon=`.
#[cfg(target_os = "linux")]
pub const HICOLOR_FILE: &str = "zenman.png";

/// The window/taskbar/Dock icon, decoded once.
///
/// `None` — and so the platform default, which is what a build with a missing asset should get — if
/// the embedded PNG will not decode. A window is not worth a boot failure over its own picture.
pub fn window_icon() -> Option<egui::IconData> {
    static ICON: OnceLock<Option<egui::IconData>> = OnceLock::new();
    ICON.get_or_init(|| match eframe::icon_data::from_png_bytes(ICON_PNG) {
        Ok(icon) => Some(icon),
        Err(e) => {
            log::warn!("zenman: the embedded application icon did not decode ({e}); using the platform default");
            None
        }
    })
    .clone()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_embedded_png_decodes_to_an_icon_the_shells_want() {
        let icon = window_icon().expect("the embedded PNG decodes");
        assert_eq!(
            (icon.width, icon.height),
            (256, 256),
            "{:?}",
            (icon.width, icon.height)
        );
        assert_eq!(icon.rgba.len(), 256 * 256 * 4, "RGBA8, exactly");
        assert!(icon.rgba.iter().any(|byte| *byte != 0), "not a blank image");
    }
}
